package com.bank.rank;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RankingDemo {
    private static final Logger log = Logger.getLogger(RankingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));
        log.info(() -> "Ranking for " + rajesh.getAccountId() + ", " + priya.getAccountId());

        RankingService svc = new RankingService();

        // sort (in place) then binarySearch (requires sorted).
        long[] balances = {250000, 1000000, 500000, 75000};
        long[] sorted = svc.sortBalances(balances);
        log.info(() -> "sorted balances = " + Arrays.toString(sorted));
        log.info(() -> "contains 500000 = " + svc.contains(sorted, 500000));
        log.info(() -> "contains 999 = " + svc.contains(sorted, 999));

        // asList is FIXED-SIZE: add throws. Demonstrate then fix with copy.
        String[] flagged = {"SAV2001", "CUR3001"};
        try {
            List<String> view = Arrays.asList(flagged);
            view.add("SAV9999");    // throws UnsupportedOperationException
        } catch (UnsupportedOperationException e) {
            log.warning("Arrays.asList add failed (fixed-size view) — as expected");
        }
        List<String> watchlist = svc.mutableWatchlist(flagged);
        watchlist.add("SAV9999");   // works: independent ArrayList
        log.info(() -> "mutable watchlist = " + watchlist);

        // Primitive array asList trap vs correct boxed conversion.
        int[] amounts = {45000, 12000, 30000};
        log.warning(() -> "Arrays.asList(int[]) size = "
                + Arrays.asList(amounts).size() + " (ONE element — the array!)");
        List<Integer> boxed = svc.boxedAmounts(amounts);
        log.info(() -> "boxed amounts size = " + boxed.size() + " = " + boxed);
    }
}

