class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in service/RankingService.java in a real project ───
class RankingService {
    private static final Logger log = Logger.getLogger(RankingService.class.getName());

    // copyOf avoids mutating the caller's array; sort orders it in place.
    long[] sortBalances(long[] input) {
        long[] copy = Arrays.copyOf(input, input.length);
        Arrays.sort(copy);   // dual-pivot quicksort for primitives
        return copy;
    }

    // binarySearch REQUIRES a sorted array; negative result means not found.
    boolean contains(long[] sorted, long key) {
        return Arrays.binarySearch(sorted, key) >= 0;
    }

    // new ArrayList(asList) = independent, growable copy (add works).
    List<String> mutableWatchlist(String[] flagged) {
        return new ArrayList<>(Arrays.asList(flagged));
    }

    // Correct primitive->element list via stream (NOT Arrays.asList).
    List<Integer> boxedAmounts(int[] amounts) {
        return Arrays.stream(amounts).boxed().toList();
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
